/**
 * Types shared by the metadata providers and the finders that consume them.
 */

export interface SeriesResult {
  series: string
  sequence?: string
}

/**
 * Error object some providers return in place of a result list
 */
export interface ProviderError {
  errorCode: 404 | 500
  errorMsg?: string
}

/**
 * Common shape of a book search result across all book providers.
 * Each provider returns a subset of these fields.
 * `descriptionPlain` and `matchConfidence` are added by BookFinder.
 */
export interface BookSearchResult {
  id?: string | number
  title?: string
  subtitle?: string | null
  author?: string | null
  narrator?: string | null
  publisher?: string | null
  publishedYear?: string | number | null
  description?: string | null
  descriptionPlain?: string
  cover?: string | null
  covers?: string[]
  isbn?: string | null
  asin?: string
  genres?: string[] | null
  tags?: string[] | null
  series?: SeriesResult[] | null
  language?: string | null
  duration?: number
  matchConfidence?: number | null
}
import axios, { AxiosError } from 'axios'
import type { ProviderError } from './types'

/**
 * Edition as returned by the Open Library ISBN endpoint
 * @see https://openlibrary.org/dev/docs/api/books
 */
type OpenLibraryEdition = Record<string, unknown>

/**
 * Works data as returned by the Open Library works endpoint (only the fields used)
 */
interface OpenLibraryWorks {
  covers?: number[]
  description?: string | { value?: string }
  first_publish_date?: string
}

interface OpenLibraryWorksResult {
  id: string | undefined
  key: string
  covers: string[]
  first_publish_date: string | undefined
  description: string | null
}

/**
 * Search doc as returned by the Open Library search endpoint (only the fields used)
 */
interface OpenLibrarySearchDoc {
  key: string
  title: string
  author_name?: string[]
  first_publish_year?: number
  cover_edition_key?: string
}

interface OpenLibrarySearchResponse {
  docs: OpenLibrarySearchDoc[]
}

/**
 * Search result. When the works request fails the error fields are spread in instead of the works data
 */
type OpenLibraryBookResult = {
  title: string
  author: string | null
  publishedYear: string | null
  edition: string | undefined
  cover: string | null
} & (OpenLibraryWorksResult | ProviderError)

class OpenLibrary {
  #responseTimeout = 10000

  baseUrl: string

  constructor() {
    this.baseUrl = 'https://openlibrary.org'
  }

  get<T>(uri: string, timeout: number = this.#responseTimeout): Promise<T | null> {
    if (!timeout || isNaN(timeout)) timeout = this.#responseTimeout
    return axios
      .get<T>(`${this.baseUrl}/${uri}`, {
        timeout
      })
      .then((res) => {
        return res.data
      })
      .catch((error: AxiosError) => {
        console.error('Failed', error.message)
        return null
      })
  }

  async isbnLookup(isbn: string): Promise<OpenLibraryEdition | ProviderError> {
    var lookupData = await this.get<OpenLibraryEdition>(`/isbn/${isbn}`)
    if (!lookupData) {
      return {
import Logger = require('../Logger')
import iTunes = require('../providers/iTunes')

class PodcastFinder {
  iTunesApi: iTunes

  constructor() {
    this.iTunesApi = new iTunes()
  }

  async search(term: string, options: { country?: string } = {}): Promise<iTunes.iTunesPodcastSearchResult[] | null> {
    if (!term) return null
    Logger.debug(`[iTunes] Searching for podcast with term "${term}"`)
    const results = await this.iTunesApi.searchPodcasts(term, options)
    Logger.debug(`[iTunes] Podcast search for "${term}" returned ${results.length} results`)
    return results
  }

  async findCovers(term: string): Promise<string[] | null> {
    if (!term) return null
    Logger.debug(`[iTunes] Searching for podcast covers with term "${term}"`)
    const results = await this.iTunesApi.searchPodcasts(term)
    if (!results) return []
    return results.map((r) => r.cover).filter((r): r is string => !!r)
  }
}
export = new PodcastFinder()

