 * Name #1 => { name: 'Name', sequence: '1' }
 *
 * @param {string} seriesString
 * @returns {{name: string, sequence: string}|null}
 */
module.exports.parse = (seriesString) => {
  if (!seriesString || typeof seriesString !== 'string') return null

  let sequence = null
