  // Series sequence match any characters after " #" other than whitespace and another #
  //  e.g. "Name #1a" is valid. "Name #1#a" or "Name #1 a" is not valid.
  const matchResults = seriesString.match(/ #([^#\s]+)$/) // Pull out sequence #
